def run_command(command, timeout=None, cwd=None, **kwargs):
    """以员工身份在家目录内执行命令，记录 job 台账。"""
    timeout = timeout or TOOL_TIMEOUT
    safe, reason = is_safe_command(command)
    if not safe:
        return {'success': False, 'error': reason, 'returncode': -1}

    job_id = 'job-%s' % uuid.uuid4().hex[:8]
    record = {'job_id': job_id, 'command': command, 'status': 'running',
              'started_at': datetime.now().isoformat()}
    _jobs[job_id] = record

    work_dir = cwd or HOME
    try:
        proc = subprocess.run(
            command, shell=True, cwd=work_dir, capture_output=True,
            text=True, timeout=timeout)
        record.update({
            'status': 'completed',
            'exit_code': proc.returncode,
            'stdout': proc.stdout[-OUTPUT_LIMIT:],
            'stderr': proc.stderr[-OUTPUT_LIMIT:],
        })
    except subprocess.TimeoutExpired:
        record.update({'status': 'timeout', 'exit_code': -1, 'stdout': '',
                       'stderr': '命令执行超时（%ds）' % timeout})
    except Exception as e:  # noqa: BLE001
        record.update({'status': 'failed', 'exit_code': -1,
                       'stdout': '', 'stderr': str(e)})
    record['finished_at'] = datetime.now().isoformat()

    return {
        'success': record.get('exit_code') == 0,
        'job_id': job_id,
        'exit_code': record.get('exit_code'),
        'stdout': record.get('stdout', ''),
        'stderr': record.get('stderr', ''),
    }


def read_file(path, max_lines=500, offset=0, **kwargs):
    fpath = Path(path).expanduser()
    if not fpath.exists():
        return {'success': False, 'error': '文件不存在: %s' % path}
    try:
        lines = fpath.read_text(encoding='utf-8', errors='replace').splitlines()
    except OSError as e:
        return {'success': False, 'error': str(e)}
    chunk = lines[offset:offset + max_lines]
    content = '\n'.join(chunk)
    if len(lines) > offset + max_lines:
        content += '\n... [截断，共 %d 行，已显示 %d-%d 行]' % (
            len(lines), offset + 1, offset + len(chunk))
    return {'success': True, 'content': content, 'total_lines': len(lines)}


def write_file(path, content='', create_dirs=True, **kwargs):
    fpath = Path(path).expanduser()
    try:
        if create_dirs:
            fpath.parent.mkdir(parents=True, exist_ok=True)
        fpath.write_text(content, encoding='utf-8')
    except OSError as e:
        return {'success': False, 'error': str(e)}
    return {'success': True, 'path': str(fpath),
            'bytes': len(content.encode('utf-8'))}


def list_dir(path='.', pattern='', **kwargs):
    dpath = Path(path).expanduser()
    if not dpath.exists():
        return {'success': False, 'error': '目录不存在: %s' % path}
    try:
        items = sorted(dpath.iterdir())
    except OSError as e:
        return {'success': False, 'error': str(e)}
    if pattern:
        import fnmatch
        items = [i for i in items if fnmatch.fnmatch(i.name, pattern)]
    entries = []
    for item in items[:100]:
        entries.append({
            'name': item.name,
            'type': 'dir' if item.is_dir() else 'file',
            'size': item.stat().st_size if item.is_file() else None,
        })
    return {'success': True, 'entries': entries, 'total': len(items)}


def find_files(base_dir='.', name_pattern='*', max_results=50, **kwargs):
    bpath = Path(base_dir).expanduser()
    if not bpath.exists():
        return {'success': False, 'error': '目录不存在: %s' % base_dir}
    matches = []
    try:
        for fpath in bpath.rglob(name_pattern):
            if fpath.is_file():
                matches.append(str(fpath))
            if len(matches) >= max_results:
                break
    except OSError as e:
        return {'success': False, 'error': str(e)}
    return {'success': True, 'files': matches}


def grep(pattern, path='.', max_results=50, **kwargs):
    p = Path(path).expanduser()
    if not p.exists():
        return {'success': False, 'error': '路径不存在: %s' % path}
    try:
        regex = re.compile(pattern)
    except re.error as e:
        return {'success': False, 'error': '无效正则: %s' % e}
    results = []
    files = [p] if p.is_file() else [f for f in p.rglob('*') if f.is_file()]
    for f in files:
        try:
            text = f.read_text(encoding='utf-8', errors='ignore')
        except OSError:
            continue
        for i, line in enumerate(text.splitlines(), 1):
            if regex.search(line):
                results.append({'file': str(f), 'line': i,
                                'text': line[:200]})
                if len(results) >= max_results:
                    return {'success': True, 'matches': results,
                            'truncated': True}
    return {'success': True, 'matches': results}


def check_env(command, **kwargs):
    """检查命令是否存在及版本。"""
    from ..core.tool_probe import find_binary_simple
    binary, status = find_binary_simple(command)
    if not binary:
        return {'available': False, 'command': command,
                'error': '未安装'}
    path = binary
    version = ''
    for vflag in ('--version', '-v', '-V', 'version'):
        try:
            vr = subprocess.run('%s %s' % (command, vflag), shell=True,
                                capture_output=True, text=True, timeout=5)
            if vr.returncode == 0 and vr.stdout.strip():
                version = vr.stdout.strip().splitlines()[0][:100]
                break
        except (subprocess.TimeoutExpired, OSError):
            continue
    return {'available': True, 'path': path, 'version': version or 'unknown'}


